// Rechnet je Anlage zwei getrennte Termine aus: die vertragliche Wartung und die
// gesetzlich vorgeschriebene Pruefung. Warum getrennt: Eine verpasste Wartung kostet
// Geld, eine verpasste Pruefung kostet den Versicherungsschutz — die Pruefung hat
// deshalb immer Vorrang und einen laengeren Vorlauf.
const VORLAUF_WARTUNG_TAGE = 45;
const VORLAUF_PRUEFUNG_TAGE = 60;
const TAG_MS = 86400000;

// Deutsche Datumsangaben (TT.MM.JJJJ) sicher einlesen — Sheets liefert sie als Text,
// new Date('01.03.2026') wuerde je nach Umgebung falsch oder gar nicht parsen.
function datumLesen(wert) {
  if (!wert) return null;
  const t = String(wert).trim();
  const de = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) return new Date(Number(de[3]), Number(de[2]) - 1, Number(de[1]));
  const iso = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
  return null;
}

function monateDazu(datum, monate) {
  const d = new Date(datum.getTime());
  d.setMonth(d.getMonth() + Number(monate));
  return d;
}

const zweiStellig = (n) => String(n).padStart(2, '0');
const datumDe = (d) => (d ? `${zweiStellig(d.getDate())}.${zweiStellig(d.getMonth() + 1)}.${d.getFullYear()}` : null);

const heute = new Date();
heute.setHours(0, 0, 0, 0);

const raus = [];
for (const eintrag of $input.all()) {
  const a = eintrag.json;

  const letzteWartung = datumLesen(a.Letzte_Wartung);
  const wartungsintervall = Number(a.Wartungsintervall_Monate) || 0;
  const letztePruefung = datumLesen(a.Letzte_Pruefung);
  const pruefintervall = Number(a.Pruefintervall_Monate) || 0;

  const naechsteWartung = letzteWartung && wartungsintervall ? monateDazu(letzteWartung, wartungsintervall) : null;
  const naechstePruefung = letztePruefung && pruefintervall ? monateDazu(letztePruefung, pruefintervall) : null;

  const tageWartung = naechsteWartung ? Math.round((naechsteWartung - heute) / TAG_MS) : null;
  const tagePruefung = naechstePruefung ? Math.round((naechstePruefung - heute) / TAG_MS) : null;

  const wartungFaellig = tageWartung !== null && tageWartung <= VORLAUF_WARTUNG_TAGE;
  const pruefungFaellig = tagePruefung !== null && tagePruefung <= VORLAUF_PRUEFUNG_TAGE;
  const pruefungUeberfaellig = tagePruefung !== null && tagePruefung < 0;
  const wartungUeberfaellig = tageWartung !== null && tageWartung < 0;

  // Datenluecken sichtbar machen statt stillschweigend ueberspringen — eine Anlage
  // ohne Intervall faellt sonst fuer immer aus der Planung.
  const datenLuecke = !letzteWartung || !wartungsintervall || (a.Gesetzliche_Pruefung && !pruefintervall);

  let prioritaet = 'normal';
  if (pruefungUeberfaellig) prioritaet = 'kritisch';
  else if (wartungUeberfaellig || (pruefungFaellig && tagePruefung <= 30)) prioritaet = 'hoch';

  // Der frueheste der beiden Termine bestimmt, wann angeschrieben wird.
  const kandidaten = [tageWartung, tagePruefung].filter((t) => t !== null);
  const tageBisFaelligkeit = kandidaten.length ? Math.min(...kandidaten) : null;

  raus.push({
    json: {
      anlage_id: a.Anlage_ID ?? '',
      kunde: a.Kunde ?? '',
      kunde_mail: a.Kunde_Mail ?? '',
      standort: a.Standort ?? '',
      anlagentyp: a.Anlagentyp ?? '',
      letzte_wartung: datumDe(letzteWartung),
      wartungsintervall_monate: wartungsintervall,
      naechste_wartung: datumDe(naechsteWartung),
      tage_bis_wartung: tageWartung,
      gesetzliche_pruefung: a.Gesetzliche_Pruefung || null,
      pruefintervall_monate: pruefintervall,
      letzte_pruefung: datumDe(letztePruefung),
      naechste_pruefung: datumDe(naechstePruefung),
      tage_bis_pruefung: tagePruefung,
      pruefung_ueberfaellig: pruefungUeberfaellig,
      wartung_ueberfaellig: wartungUeberfaellig,
      tage_bis_faelligkeit: tageBisFaelligkeit,
      prioritaet,
      daten_luecke: datenLuecke,
      letztes_anschreiben: a.Letztes_Anschreiben || null,
      handlungsbedarf: Boolean(wartungFaellig || pruefungFaellig || datenLuecke),
      lauf_datum: datumDe(heute)
    }
  });
}

// Kritische Faelle nach oben — die Disposition arbeitet die Liste von oben ab.
const rang = { kritisch: 0, hoch: 1, normal: 2 };
raus.sort((x, y) => (rang[x.json.prioritaet] - rang[y.json.prioritaet]) || ((x.json.tage_bis_faelligkeit ?? 9999) - (y.json.tage_bis_faelligkeit ?? 9999)));
return raus;

// Ordnet die Rueckmeldungen aus dem Antwortformular den faelligen Anlagen zu.
// Warum das vor dem Mailversand passiert: Wer letzte Woche schon zugesagt hat, darf
// nicht erneut angeschrieben werden — genau daran scheitern die meisten
// Wartungserinnerungen in der Praxis.
const faellige = $('Faelligkeiten berechnen').all().map((e) => e.json);

// Rueckmeldungen liegen chronologisch vor; die juengste pro Anlage gewinnt.
const antworten = new Map();
for (const eintrag of $input.all()) {
  const r = eintrag.json;
  const id = String(r.Anlage_ID ?? '').trim();
  if (!id) continue;
  antworten.set(id, {
    antwort: String(r.Antwort ?? '').trim().toLowerCase(),
    wunschtermin: r.Wunschtermin || null,
    eingang: r.Eingang || null
  });
}

const raus = [];
for (const anlage of faellige) {
  if (!anlage.handlungsbedarf) continue;

  const r = antworten.get(String(anlage.anlage_id).trim());
  const zugesagt = Boolean(r && ['zusage', 'ja', 'bestaetigt', 'bestätigt'].includes(r.antwort));
  const rueckruf = Boolean(r && ['rueckruf', 'rückruf', 'telefon'].includes(r.antwort));
  const abgesagt = Boolean(r && ['absage', 'nein'].includes(r.antwort));

  // Fallunterscheidung fuer die Weiche: erst Rueckmeldung, dann Erinnerung,
  // dann Erstanschreiben. Ohne Mailadresse geht nichts raus.
  let fall;
  if (anlage.daten_luecke && !anlage.naechste_wartung && !anlage.naechste_pruefung) fall = 'pruefen';
  else if (!anlage.kunde_mail) fall = 'pruefen';
  else if (r) fall = 'rueckmeldung';
  else if (anlage.letztes_anschreiben) fall = 'erinnerung';
  else fall = 'erstanschreiben';

  raus.push({
    json: {
      ...anlage,
      bearbeitungsfall: fall,
      rueckmeldung_vorhanden: Boolean(r),
      rueckmeldung_art: r ? r.antwort : null,
      rueckmeldung_wunschtermin: r ? r.wunschtermin : null,
      rueckmeldung_eingang: r ? r.eingang : null,
      termin_steht: zugesagt,
      rueckruf_gewuenscht: rueckruf,
      abgesagt,
      anschreiben_grund: anlage.pruefung_ueberfaellig
        ? `Gesetzliche Pruefung (${anlage.gesetzliche_pruefung || 'Pruefpflicht'}) seit ${Math.abs(anlage.tage_bis_pruefung)} Tagen ueberfaellig`
        : (anlage.wartung_ueberfaellig
          ? `Wartung seit ${Math.abs(anlage.tage_bis_wartung)} Tagen ueberfaellig`
          : `Faellig in ${anlage.tage_bis_faelligkeit} Tagen`)
    }
  });
}
return raus;
